from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(1,'numeration','Entiers et décimaux','1 · Nombres et calculs',
'Milliards · Unités de numération · Écritures d’un nombre',
['Lire, écrire et décomposer de grands nombres, jusqu’aux milliards.','Connaître les liens entre unités, dixièmes, centièmes et millièmes.','Reconnaître un nombre décimal et passer d’une écriture à une autre.'],
['Numération du CM2 : entiers jusqu’aux centaines de millions, décimaux jusqu’aux millièmes.'],[
page(1,'Les grands nombres et les milliards',
bloc('definition',r'Les chiffres d’un entier se regroupent par classes de trois, de droite à gauche : unités, mille, millions, milliards. Un milliard, c’est mille millions : $1\,000\,000\,000$. Le nombre $7\,342\,015\,608$ se lit « sept-milliards-trois-cent-quarante-deux-millions-quinze-mille-six-cent-huit ».'),
tableau(['Classe','milliards','millions','mille','unités'],[['Rangs','c d u','c d u','c d u','c d u'],['Chiffres','7','3 4 2','0 1 5','6 0 8']]),
bloc('savoirfaire',r'Dans $7\,342\,015\,608$, le chiffre des millions est 2, mais le nombre de millions est $7\,342$ : on lit tout ce qui est écrit à gauche de ce rang, ce rang compris.','Chiffre ou nombre de'),
sec(2,'Unités, dixièmes, centièmes et millièmes'),
bloc('propriete',r'Chaque rang vaut dix fois le rang situé à sa droite. Ainsi $1=\frac{10}{10}=\frac{100}{100}=\frac{1\,000}{1\,000}$ ; $\frac1{10}=\frac{10}{100}$ ; $\frac1{100}=\frac{10}{1\,000}$. Dans l’autre sens : $1=10\times\frac1{10}=100\times\frac1{100}$ et $\frac1{10}=10\times\frac1{100}$.'),
r'@FIG:cours-centiemes@',
bloc('exemple',r'$\frac1{10}=0{,}1$ ; $\frac1{100}=0{,}01$ ; $\frac1{1\,000}=0{,}001$. Trois dixièmes et quatre centièmes s’écrivent $0{,}34$ : c’est aussi $\frac{34}{100}$, trente-quatre centièmes.')),
page(3,'Reconnaître un nombre décimal',
bloc('definition',r'Un nombre décimal est un nombre qui peut s’écrire avec une fraction décimale, c’est-à-dire une fraction de dénominateur 10, 100, $1\,000$… Par exemple $2{,}5=\frac{25}{10}$ ; $\frac34=\frac{75}{100}$ ; $7=\frac{70}{10}$. Tout nombre entier est donc aussi un nombre décimal.'),
bloc('attention',r'Un nombre décimal n’est pas fait de deux entiers séparés par une virgule : dans $3{,}12$, la partie 12 compte des centièmes. Certaines fractions ne sont pas des nombres décimaux, comme $\frac13$ : le chapitre 5 explique pourquoi.'),
sec(4,'Passer d’une écriture à une autre'),
bloc('propriete',r'Un même nombre a plusieurs écritures : $4{,}107=\frac{4\,107}{1\,000}=4+\frac{107}{1\,000}=4+\frac1{10}+\frac7{1\,000}$. L’écriture $4+\frac{107}{1\,000}$, un entier plus une fraction plus petite que 1, s’appelle un nombre mixte.'),
bloc('savoirfaire',r'Pour passer de la virgule à la fraction, on regarde le rang du dernier chiffre : $0{,}045$ se termine aux millièmes, donc $0{,}045=\frac{45}{1\,000}$. Dans l’autre sens, $\frac{2\,375}{100}$ compte des centièmes : $\frac{2\,375}{100}=23{,}75$.','Lire le dernier rang'),
bloc('exemple',r'Un zéro écrit à droite de la partie décimale ne change pas le nombre : $2{,}5=2{,}50=2{,}500$, car 5 dixièmes font 50 centièmes, ou 500 millièmes.')),
],[
E('Lire un grand nombre',r'Écrire en lettres le nombre $3\,052\,400\,000$, puis écrire en chiffres « douze-milliards-cinq-cents-millions ».',r'On lit classe par classe : « trois-milliards-cinquante-deux-millions-quatre-cent-mille ». Le second nombre s’écrit $\res{12\,500\,000\,000}$ : 12 dans la classe des milliards, 500 dans celle des millions.','Lire et écrire classe par classe.','assert 3*10**9+52*10**6+400*10**3==3052400000 and 12*10**9+500*10**6==12500000000'),
E('Chiffre ou nombre',r'Dans $7\,342\,015\,608$, donner le chiffre des millions et le nombre de millions, puis le chiffre des centaines de mille et le nombre de centaines de mille.',r'Chiffre des millions : $\res2$ ; nombre de millions : $\res{7\,342}$. Chiffre des centaines de mille : $\res0$ ; nombre de centaines de mille : $\res{73\,420}$.','Pour un nombre de…, garder tout ce qui est à gauche du rang.','n=7342015608\nassert n//10**6%10==2 and n//10**6==7342 and n//10**5%10==0 and n//10**5==73420'),
E('Unités de numération',r'Compléter : $1=\square$ dixièmes ; 1 dixième $=\square$ centièmes ; 1 centième $=\square$ millièmes ; $1=\square$ millièmes ; 1 millier $=\square$ centaines.',r'$1=\res{10}$ dixièmes ; 1 dixième $=\res{10}$ centièmes ; 1 centième $=\res{10}$ millièmes ; $1=\res{1\,000}$ millièmes ; 1 millier $=\res{10}$ centaines.','Chaque rang vaut dix fois le rang de droite.','assert 10*Rational(1,10)==1 and 10*Rational(1,100)==Rational(1,10) and 10*Rational(1,1000)==Rational(1,100) and 1000*Rational(1,1000)==1 and 10*100==1000'),
E('Lire une grille',r'L’unité est un grand carré partagé en cent petits carrés. Écrire le nombre représenté par la partie colorée sous forme de fraction décimale, puis avec une virgule.',r'Deux unités entières, 4 colonnes de dixièmes et 7 petits carrés de centièmes : $2+\frac4{10}+\frac7{100}=\res{\frac{247}{100}}=\res{2{,}47}$.','Compter les unités, puis les dixièmes, puis les centièmes.','assert 2+Rational(4,10)+Rational(7,100)==Rational(247,100)==Rational("2.47")',figure='num-4'),
E('Fractions décimales',r'Écrire avec une virgule : $\frac7{10}$ ; $\frac{45}{100}$ ; $\frac3{1\,000}$ ; $4+\frac1{10}+\frac7{1\,000}$.',r'$\res{0{,}7}$ ; $\res{0{,}45}$ ; $\res{0{,}003}$ ; $\res{4{,}107}$, car il n’y a aucun centième.','Le dénominateur indique le rang du dernier chiffre.','assert Rational(7,10)==Rational("0.7") and Rational(45,100)==Rational("0.45") and Rational(3,1000)==Rational("0.003") and 4+Rational(1,10)+Rational(7,1000)==Rational("4.107")'),
E('Valeur des chiffres',r'Dans le nombre $58{,}036$, donner la valeur de chacun des chiffres.',r'5 dizaines : 50 ; 8 unités : 8 ; 0 dixième ; 3 centièmes : $0{,}03$ ; 6 millièmes : $0{,}006$. Contrôle : $50+8+0{,}03+0{,}006=\res{58{,}036}$.','Associer chaque chiffre à son rang.','assert 50+8+Rational("0.03")+Rational("0.006")==Rational("58.036")'),
E('Le même nombre ?',r'Parmi ces écritures, lesquelles désignent le nombre $3{,}4$ ? $\frac{34}{10}$ ; $3+\frac4{100}$ ; $\frac{340}{100}$ ; $3+\frac4{10}$ ; $\frac{34}{100}$.',r'Conviennent : $\res{\frac{34}{10}}$, $\res{\frac{340}{100}}$ et $\res{3+\frac4{10}}$. En revanche $3+\frac4{100}=3{,}04$ et $\frac{34}{100}=0{,}34$.','Écrire chaque proposition avec une virgule.','assert Rational(34,10)==Rational(340,100)==3+Rational(4,10)==Rational("3.4") and 3+Rational(4,100)!=Rational("3.4") and Rational(34,100)!=Rational("3.4")'),
E('Nombres mixtes',r'Écrire chaque nombre comme un entier plus une fraction décimale plus petite que 1, puis avec une virgule : $\frac{2\,375}{1\,000}$ ; $\frac{1\,204}{100}$ ; $\frac{89}{10}$.',r'$\frac{2\,375}{1\,000}=\res{2+\frac{375}{1\,000}}=2{,}375$ ; $\frac{1\,204}{100}=\res{12+\frac4{100}}=12{,}04$ ; $\frac{89}{10}=\res{8+\frac9{10}}=8{,}9$.','Extraire les unités entières du numérateur.','assert Rational(2375,1000)==2+Rational(375,1000)==Rational("2.375") and Rational(1204,100)==12+Rational(4,100)==Rational("12.04") and Rational(89,10)==8+Rational(9,10)'),
E('Décimal ou pas ?',r'Montrer que chacun de ces nombres est décimal en l’écrivant avec une fraction décimale, puis avec une virgule : $\frac34$ ; $7$ ; $\frac15$ ; $\frac2{25}$.',r'$\frac34=\res{\frac{75}{100}}=0{,}75$ ; $7=\res{\frac{70}{10}}$ ; $\frac15=\res{\frac2{10}}=0{,}2$ ; $\frac2{25}=\res{\frac8{100}}=0{,}08$.','Multiplier numérateur et dénominateur pour obtenir 10, 100 ou 1 000.','assert Rational(3,4)==Rational(75,100) and 7==Rational(70,10) and Rational(1,5)==Rational(2,10) and Rational(2,25)==Rational(8,100)'),
E('Distances dans l’espace',r'La distance moyenne de la Terre au Soleil est d’environ 150 millions de kilomètres ; celle de Neptune au Soleil, d’environ $4{,}5$ milliards de kilomètres. Écrire ces deux distances en chiffres, puis trouver combien de fois la première est contenue dans la seconde.',r'$150$ millions : $\res{150\,000\,000}$ km. $4{,}5$ milliards, c’est 4 milliards et 500 millions : $\res{4\,500\,000\,000}$ km. En millions : $4\,500:150=\res{30}$ fois.','Compter en millions pour comparer.','assert 4500*10**6//(150*10**6)==30 and 4500*10**6%(150*10**6)==0'),
E('Huit milliards d’humains',r'Selon l’ONU, la population mondiale a atteint 8 milliards de personnes en novembre 2022 ; elle était de 4 milliards en 1974. Écrire ces deux nombres en chiffres. Combien de millions de personnes de plus en 2022 ? Combien de fois plus ?',r'$\res{8\,000\,000\,000}$ et $\res{4\,000\,000\,000}$. L’écart vaut 4 milliards, soit $\res{4\,000}$ millions de personnes. La population a été multipliée par $\res2$ en 48 ans.','Un milliard vaut mille millions.','assert 8*10**9-4*10**9==4000*10**6 and 8*10**9==2*4*10**9 and 2022-1974==48'),
E('Des boîtes de mille',r'Une usine fabrique $2\,450\,000\,000$ vis par an. Elle les range par boîtes de $1\,000$ vis, puis place les boîtes dans des cartons de $1\,000$ boîtes. Combien de boîtes remplit-elle ? Combien de cartons ?',r'Le nombre de milliers de vis donne les boîtes : $\res{2\,450\,000}$ boîtes. Un carton contient un million de vis : le nombre de millions donne $\res{2\,450}$ cartons.','Lire un nombre de milliers, puis de millions.','n=2450000000\nassert n//1000==2450000 and n%1000==0 and n//10**6==2450 and n%10**6==0'),
E('Le nombre mystère',r'Je suis un nombre décimal. J’ai 3 unités et aucun centième ; mon chiffre des dixièmes est 4 et mon chiffre des millièmes est le double de celui des dixièmes. Je n’ai pas d’autre chiffre non nul. Qui suis-je ? Donner aussi mon écriture en fraction décimale.',r'Unités 3, dixièmes 4, centièmes 0, millièmes $2\times4=8$ : le nombre est $\res{3{,}408}$, soit $\res{\frac{3\,408}{1\,000}}$.','Remplir les rangs un à un.','assert 3+Rational(4,10)+Rational(0,100)+Rational(8,1000)==Rational("3.408")==Rational(3408,1000)'),
E('La notation de Stevin',r'En 1585, le savant Simon Stevin écrivait 27\stevin{0}8\stevin{1}4\stevin{2}7\stevin{3} pour $27{,}847$ : le chiffre entouré indique le rang (0 pour les unités, 1 pour les dixièmes, 2 pour les centièmes…). Écrire $5{,}306$ avec sa notation, puis écrire avec une virgule le nombre 3\stevin{0}0\stevin{1}9\stevin{2}.',r'$5{,}306$ s’écrit 5\stevin{0}3\stevin{1}0\stevin{2}6\stevin{3}. Le nombre 3\stevin{0}0\stevin{1}9\stevin{2} a 3 unités, 0 dixième et 9 centièmes : $\res{3{,}09}$.','Associer chaque indice à un rang.','assert 3+Rational(0,10)+Rational(9,100)==Rational("3.09") and 5+Rational(3,10)+Rational(0,100)+Rational(6,1000)==Rational("5.306")'),
E('Vrai ou faux',r'Léa affirme : « Dans $6{,}25$, il y a 25 dixièmes. » A-t-elle raison ? Combien de dixièmes, puis combien de centièmes, le nombre $6{,}25$ contient-il ?',r'Elle a $\res{\text{tort}}$. $6{,}25$ contient $\res{62}$ dixièmes (et encore 5 centièmes), et en tout $\res{625}$ centièmes. Le chiffre des dixièmes est 2, mais le nombre de dixièmes est 62.','Distinguer le chiffre et le nombre de dixièmes.','assert int(Rational("6.25")*10)==62 and Rational("6.25")*100==625')
],reperes=['Grands nombres et milliards','Unités de numération et valeur des chiffres','Nombres décimaux et fractions décimales','Écritures d’un même nombre'],deco='calcul')

chapitre(2,'reperage','Repérer, comparer et arrondir','1 · Nombres et calculs',
'Demi-droite · Ordre · Encadrement · Arrondi',
['Lire et placer une abscisse décimale sur une demi-droite graduée.','Comparer, ranger, encadrer et intercaler des nombres décimaux.','Donner l’arrondi d’un nombre à l’unité, au dixième ou au centième.'],
['Valeur des chiffres selon leur rang ; lecture d’une graduation.'],[
page(1,'Lire et construire une graduation',
bloc('definition',r'Sur une demi-droite graduée, l’origine est repérée par 0 et une même longueur, l’unité, est reportée régulièrement. Chaque point est repéré par un nombre, appelé son abscisse.'),
r'@FIG:cours-droite-zoom@',
bloc('savoirfaire',r'Entre 3 et 4, il y a dix intervalles égaux : chacun vaut $0{,}1$. Entre $3{,}4$ et $3{,}5$, dix intervalles encore : chacun vaut $0{,}01$. On cherche toujours la valeur d’un petit intervalle avant de lire.','Lire une graduation'),
sec(2,'Comparer et ordonner des décimaux'),
bloc('propriete',r'Pour comparer deux nombres décimaux, on compare les parties entières, puis les dixièmes, puis les centièmes… $12{,}7>12{,}69$, car 7 dixièmes est plus que 6 dixièmes. Écrire le même nombre de décimales aide : $12{,}70>12{,}69$.'),
bloc('attention',r'Le nombre de chiffres ne décide pas : $0{,}8>0{,}75$ alors que 75 est plus grand que 8. On compare rang par rang, en commençant par la gauche.')),
page(3,'Encadrer et intercaler',
bloc('definition',r'Encadrer un nombre, c’est le placer entre deux nombres. $3<3{,}47<4$ est un encadrement à l’unité ; $3{,}4<3{,}47<3{,}5$ est un encadrement au dixième.'),
bloc('savoirfaire',r'Entre $2{,}3$ et $2{,}4$, écrire $2{,}30$ et $2{,}40$ fait apparaître d’autres nombres : $2{,}31$, $2{,}35$… Entre deux décimaux différents, on peut toujours en intercaler un autre.','Intercaler'),
sec(4,'Arrondir et approcher un nombre'),
bloc('definition',r'L’arrondi à l’unité d’un nombre est l’entier le plus proche ; l’arrondi au dixième, le nombre à une décimale le plus proche ; de même au centième. Si le chiffre qui suit le rang voulu est 5, 6, 7, 8 ou 9, on arrondit au-dessus ; sinon, au-dessous.'),
r'@FIG:cours-arrondi@',
bloc('exemple',r'$7{,}364$ s’arrondit à 7 à l’unité, à $7{,}4$ au dixième et à $7{,}36$ au centième. Certains nombres ne s’écrivent pas avec un nombre fini de décimales, comme $\frac13=0{,}333\ldots$ : on utilise alors une valeur arrondie, $0{,}33$ au centième.')),
],[
E('Lire des abscisses',r'La demi-droite est graduée en dixièmes. Lire les abscisses des points A, B et C.',r'Chaque petit intervalle vaut $0{,}1$. A : $\res{0{,}6}$ ; B : $\res{1{,}3}$ ; C : $\res{2{,}8}$.','Trouver la valeur d’un petit intervalle.','assert Rational(6,10)==Rational("0.6") and 1+Rational(3,10)==Rational("1.3") and 2+Rational(8,10)==Rational("2.8")',figure='rep-1'),
E('Placer des points',r'La demi-droite est graduée en centièmes, de $5{,}2$ à $5{,}4$. Placer les points D, E et F d’abscisses $5{,}25$ ; $5{,}38$ et $5{,}3$.',r'D est 5 centièmes après $5{,}2$ ; E est 8 centièmes après $5{,}3$ ; F est exactement sur la graduation $5{,}3$. Les positions figurent en vert.','Repérer le dixième, puis compter les centièmes.','assert Rational("5.2")+Rational(5,100)==Rational("5.25") and Rational("5.3")+Rational(8,100)==Rational("5.38")',figure='rep-2'),
E('Comparer',r'Comparer avec $<$ ou $>$ : $12{,}7$ et $12{,}69$ ; $0{,}8$ et $0{,}75$ ; $3{,}05$ et $3{,}5$ ; $7$ et $6{,}999$.',r'$\res{12{,}7>12{,}69}$ ; $\res{0{,}8>0{,}75}$ ; $\res{3{,}05<3{,}5}$ ; $\res{7>6{,}999}$.','Comparer partie entière, puis dixièmes, puis centièmes.','assert Rational("12.7")>Rational("12.69") and Rational("0.8")>Rational("0.75") and Rational("3.05")<Rational("3.5") and 7>Rational("6.999")'),
E('Ranger',r'Ranger dans l’ordre croissant : $4{,}2$ ; $4{,}02$ ; $4{,}25$ ; $4{,}205$ ; $4{,}3$.',r'Avec trois décimales : $4{,}200$ ; $4{,}020$ ; $4{,}250$ ; $4{,}205$ ; $4{,}300$. Ordre : $\res{4{,}02<4{,}2<4{,}205<4{,}25<4{,}3}$.','Écrire tous les nombres avec le même nombre de décimales.','L=[Rational("4.02"),Rational("4.2"),Rational("4.205"),Rational("4.25"),Rational("4.3")]\nassert L==sorted(L)'),
E('Arrondir',r'Donner l’arrondi à l’unité, au dixième et au centième de $7{,}364$, puis de $12{,}58$.',r'$7{,}364$ : $\res7$ ; $\res{7{,}4}$ ; $\res{7{,}36}$. $12{,}58$ : $\res{13}$ ; $\res{12{,}6}$ ; $\res{12{,}58}$, qui a déjà deux décimales.','Regarder le chiffre qui suit le rang voulu.','assert abs(Rational("7.364")-7)<Rational(1,2) and abs(Rational("7.364")-Rational("7.4"))<Rational(1,20) and abs(Rational("7.364")-Rational("7.36"))<Rational(1,200) and abs(Rational("12.58")-13)<Rational(1,2) and abs(Rational("12.58")-Rational("12.6"))<Rational(1,20)'),
E('Encadrer',r'Encadrer $15{,}738$ à l’unité, au dixième, puis au centième.',r'$\res{15<15{,}738<16}$ ; $\res{15{,}7<15{,}738<15{,}8}$ ; $\res{15{,}73<15{,}738<15{,}74}$.','Garder les chiffres jusqu’au rang voulu, puis ajouter une unité de ce rang.','x=Rational("15.738")\nassert 15<x<16 and Rational("15.7")<x<Rational("15.8") and Rational("15.73")<x<Rational("15.74")'),
E('Intercaler',r'Intercaler un nombre entre $2{,}3$ et $2{,}4$ ; entre $0{,}59$ et $0{,}6$ ; entre 8 et $8{,}01$.',r'Par exemple $\res{2{,}35}$ ; $\res{0{,}595}$ ; $\res{8{,}005}$. D’autres réponses conviennent : il suffit d’ajouter un rang.','Écrire les bornes avec une décimale de plus.','assert Rational("2.3")<Rational("2.35")<Rational("2.4") and Rational("0.59")<Rational("0.595")<Rational("0.6") and 8<Rational("8.005")<Rational("8.01")'),
E('Zoom sur la droite',r'La demi-droite est graduée en centièmes entre $1{,}4$ et $1{,}5$. Lire l’abscisse de G. Le point H est au milieu de deux graduations : donner son abscisse.',r'G est 7 centièmes après $1{,}4$ : $\res{1{,}47}$. H est au milieu entre $1{,}41$ et $1{,}42$ : $\res{1{,}415}$, soit 5 millièmes de plus que $1{,}41$.','Un demi-centième vaut 5 millièmes.','assert Rational("1.4")+Rational(7,100)==Rational("1.47") and (Rational("1.41")+Rational("1.42"))/2==Rational("1.415")',figure='rep-8'),
E('Valeurs approchées',r'On sait que $\frac13=0{,}333\ldots$ et $\frac23=0{,}666\ldots$, les chiffres se répétant sans fin. Donner les arrondis au dixième et au centième de ces deux nombres.',r'$\frac13$ : $\res{0{,}3}$ et $\res{0{,}33}$. $\frac23$ : $\res{0{,}7}$ et $\res{0{,}67}$, car le chiffre suivant est 6.','Arrondir comme pour un décimal.','assert abs(Rational(1,3)-Rational("0.3"))<Rational(1,20) and abs(Rational(1,3)-Rational("0.33"))<Rational(1,200) and abs(Rational(2,3)-Rational("0.7"))<Rational(1,20) and abs(Rational(2,3)-Rational("0.67"))<Rational(1,200)'),
E('Tous les candidats',r'Trouver tous les nombres à deux décimales dont l’arrondi au dixième est $3{,}5$. Combien y en a-t-il ?',r'Ils vont de $3{,}45$ à $3{,}54$ : $3{,}45$ ; $3{,}46$ ; … ; $3{,}54$. Il y en a $\res{10}$. $3{,}44$ s’arrondit à $3{,}4$ et $3{,}55$ à $3{,}6$.','Chercher les bornes, chiffre 5 compris.','L=[n for n in range(300,400) if (n+5)//10==35]\nassert L[0]==345 and L[-1]==354 and len(L)==10'),
E('Le saut en longueur',r'Résultats d’un concours de saut : Léna $4{,}85$ m ; Malik $4{,}9$ m ; Sofia $4{,}08$ m ; Tom $4{,}89$ m ; Inès $4{,}8$ m. Établir le classement et le podium.',r'Avec deux décimales : $4{,}90$ ; $4{,}89$ ; $4{,}85$ ; $4{,}80$ ; $4{,}08$. Podium : $\res{\text{Malik, Tom, Léna}}$ ; puis Inès et Sofia.','Comparer avec le même nombre de décimales.','L=[Rational("4.9"),Rational("4.89"),Rational("4.85"),Rational("4.8"),Rational("4.08")]\nassert L==sorted(L,reverse=True)'),
E('Les prix arrondis',r'Au marché, Yanis achète trois articles à $2{,}49$ €, $13{,}95$ € et $0{,}99$ €. Arrondir chaque prix à l’euro, estimer le total, puis calculer le prix exact.',r'Arrondis : 2 € ; 14 € ; 1 €. Estimation : $\res{17}$ €. Prix exact : $2{,}49+13{,}95+0{,}99=\res{17{,}43}$ €, proche de l’estimation.','Arrondir pour estimer, puis calculer exactement.','assert Rational("2.49")+Rational("13.95")+Rational("0.99")==Rational("17.43") and 2+14+1==17'),
E('Le chronomètre',r'Quatre coureurs ont été chronométrés : Ana $12{,}48$ s ; Bilal $12{,}4$ s ; Chloé $12{,}52$ s ; Dan $12{,}405$ s. Qui gagne ? Si le chronomètre n’affichait que les dixièmes (arrondis), pourrait-on départager tout le monde ?',r'Ordre : Bilal $12{,}400$ ; Dan $12{,}405$ ; Ana $12{,}480$ ; Chloé $12{,}520$ : $\res{\text{Bilal gagne}}$. Au dixième : Ana $12{,}5$ ; Bilal $12{,}4$ ; Chloé $12{,}5$ ; Dan $12{,}4$. $\res{\text{Non}}$ : Bilal et Dan seraient à égalité, tout comme Ana et Chloé.','Comparer les valeurs exactes, puis les arrondis.','L=[Rational("12.4"),Rational("12.405"),Rational("12.48"),Rational("12.52")]\nassert L==sorted(L) and [ (int(x*100)+5)//10 for x in [Rational("12.48"),Rational("12.4"),Rational("12.52"),Rational("12.405")] ]==[125,124,125,124]'),
E('Le nombre mystère',r'Je suis un nombre à deux décimales. Mon arrondi à l’unité est 8, mon arrondi au dixième est $7{,}6$ et mon chiffre des centièmes est 9. Qui suis-je ?',r'Arrondi au dixième $7{,}6$ : le nombre est entre $7{,}55$ et $7{,}64$. Avec 9 centièmes, seul $\res{7{,}59}$ convient ; son arrondi à l’unité est bien 8.','Utiliser l’arrondi le plus précis d’abord.','L=[n for n in range(700,900) if (n+5)//10==76 and n%10==9 and (n+50)//100==8]\nassert L==[759]'),
E('Vrai ou faux',r'Hugo affirme : « $3{,}15$ est plus grand que $3{,}9$, car 15 est plus grand que 9. » Corriger son raisonnement.',r'C’est $\res{\text{faux}}$ : les parties entières sont égales, puis 1 dixième est moins que 9 dixièmes. Donc $\res{3{,}15<3{,}9}$, comme le montre l’écriture $3{,}15<3{,}90$.','Comparer rang par rang.','assert Rational("3.15")<Rational("3.9")')
],reperes=['Demi-droite graduée et abscisses','Comparer et ranger','Encadrer et intercaler','Arrondis et valeurs approchées'],deco='calcul')

chapitre(3,'calcul-decimal','Calculer avec les décimaux','1 · Nombres et calculs',
'Addition · Soustraction · Multiplication · Contrôle',
['Additionner et soustraire des nombres décimaux.','Multiplier par 10, 100, 1 000 et par 0,1, 0,01, 0,001.','Comprendre, calculer et contrôler le produit de deux décimaux.'],
['Tables de multiplication ; opérations posées sur les entiers.'],[
page(1,'Additionner et soustraire',
bloc('savoirfaire',r'Pour poser une addition ou une soustraction, on aligne les virgules, donc les rangs, et on complète par des zéros : $12{,}70+3{,}85=16{,}55$ ; $20{,}00-7{,}35=12{,}65$. Avant de poser, on estime : $13+4=17$, proche de $16{,}55$.','Aligner les rangs'),
sec(2,'Multiplier ou diviser par 10, 100, 1 000'),
bloc('propriete',r'Multiplier par 10, 100 ou $1\,000$ rend chaque chiffre 10, 100 ou $1\,000$ fois plus grand : il avance de 1, 2 ou 3 rangs vers la gauche. $4{,}56\times100=456$. Diviser par 10, 100 ou $1\,000$ le fait reculer d’autant : $37{,}2:100=0{,}372$.'),
r'@FIG:cours-glisse@',
bloc('propriete',r'Multiplier par $0{,}1$, c’est prendre un dixième, donc diviser par 10. De même, multiplier par $0{,}01$ revient à diviser par 100, et par $0{,}001$ à diviser par $1\,000$ : $45\times0{,}1=4{,}5$ ; $6{,}2\times0{,}01=0{,}062$.')),
page(3,'Multiplier deux nombres décimaux',
bloc('exemple',r'Un rectangle de $2{,}3$ cm sur $1{,}4$ cm se découpe en quatre parties d’aires $2\times1=2$ ; $2\times0{,}4=0{,}8$ ; $0{,}3\times1=0{,}3$ et $0{,}3\times0{,}4=0{,}12$. Son aire vaut $3{,}22\ \mathrm{cm}^2$ : donc $2{,}3\times1{,}4=3{,}22$.'),
r'@FIG:cours-rectangle-produit@',
bloc('propriete',r'$2{,}3=23\times0{,}1$ et $1{,}4=14\times0{,}1$. On peut changer l’ordre des facteurs : $2{,}3\times1{,}4=23\times14\times0{,}1\times0{,}1=322\times0{,}01=3{,}22$. On multiplie sans les virgules ; le résultat a autant de décimales que les deux facteurs réunis.'),
sec(4,'Organiser et contrôler un calcul'),
bloc('savoirfaire',r'$19{,}8\times5{,}1$ est proche de $20\times5=100$. On calcule $198\times51=10\,098$ et on place deux décimales : $100{,}98$, cohérent avec l’ordre de grandeur.','Ordre de grandeur'),
bloc('attention',r'Multiplier par un nombre plus petit que 1 donne un résultat plus petit : $8\times0{,}5=4$. Multiplier n’agrandit pas toujours.')),
],[
E('Additions posées',r'Poser et calculer $12{,}7+3{,}85$, puis $45{,}08+9{,}9$.',r'$12{,}70+3{,}85=\res{16{,}55}$ ; $45{,}08+9{,}90=\res{54{,}98}$. Estimations : 17 et 55.','Aligner les virgules.','assert Rational("12.7")+Rational("3.85")==Rational("16.55") and Rational("45.08")+Rational("9.9")==Rational("54.98")'),
E('Soustractions posées',r'Poser et calculer $20-7{,}35$, puis $8{,}4-2{,}76$.',r'$20{,}00-7{,}35=\res{12{,}65}$ ; $8{,}40-2{,}76=\res{5{,}64}$. Contrôle : $12{,}65+7{,}35=20$.','Compléter par des zéros avant de soustraire.','assert 20-Rational("7.35")==Rational("12.65") and Rational("8.4")-Rational("2.76")==Rational("5.64")'),
E('Par 10, 100 ou 1 000',r'Calculer : $4{,}56\times100$ ; $0{,}37\times10$ ; $2{,}5\times1\,000$ ; $37{,}2:100$ ; $5:1\,000$.',r'$\res{456}$ ; $\res{3{,}7}$ ; $\res{2\,500}$ ; $\res{0{,}372}$ ; $\res{0{,}005}$.','Déplacer les chiffres de 1, 2 ou 3 rangs.','assert Rational("4.56")*100==456 and Rational("0.37")*10==Rational("3.7") and Rational("2.5")*1000==2500 and Rational("37.2")/100==Rational("0.372") and Rational(5,1000)==Rational("0.005")'),
E('Par 0,1 ; 0,01 ; 0,001',r'Calculer : $45\times0{,}1$ ; $6{,}2\times0{,}01$ ; $300\times0{,}001$ ; $7\times0{,}01$.',r'$\res{4{,}5}$ ; $\res{0{,}062}$ ; $\res{0{,}3}$ ; $\res{0{,}07}$ : on divise par 10, 100 ou $1\,000$.','Multiplier par 0,1 revient à diviser par 10.','assert 45*Rational("0.1")==Rational("4.5") and Rational("6.2")*Rational("0.01")==Rational("0.062") and 300*Rational("0.001")==Rational("0.3") and 7*Rational("0.01")==Rational("0.07")'),
E('Premiers produits',r'Calculer $2{,}3\times1{,}4$ ; $0{,}5\times0{,}8$ ; $1{,}2\times3$.',r'$23\times14=322$, deux décimales : $\res{3{,}22}$. $5\times8=40$, deux décimales : $\res{0{,}4}$. $12\times3=36$, une décimale : $\res{3{,}6}$.','Multiplier sans virgule, puis compter les décimales.','assert Rational("2.3")*Rational("1.4")==Rational("3.22") and Rational("0.5")*Rational("0.8")==Rational("0.4") and Rational("1.2")*3==Rational("3.6")'),
E('Avec un rectangle',r'Le rectangle mesure $3{,}2$ cm sur $2{,}5$ cm. Il est découpé en deux parties. Calculer l’aire de chaque partie, puis en déduire $3{,}2\times2{,}5$.',r'Partie de 3 cm sur $2{,}5$ cm : $7{,}5\ \mathrm{cm}^2$. Partie de $0{,}2$ cm sur $2{,}5$ cm : $0{,}5\ \mathrm{cm}^2$. Total : $3{,}2\times2{,}5=\res{8}$.','Découper le rectangle pour calculer.','assert 3*Rational("2.5")==Rational("7.5") and Rational("0.2")*Rational("2.5")==Rational("0.5") and Rational("3.2")*Rational("2.5")==8',figure='cal-6'),
E('Placer la virgule',r'On sait que $147\times23=3\,381$. En déduire $14{,}7\times2{,}3$ ; $1{,}47\times23$ ; $0{,}147\times0{,}23$ ; $147\times0{,}023$.',r'$\res{33{,}81}$ ; $\res{33{,}81}$ ; $\res{0{,}033\,81}$ ; $\res{3{,}381}$ : deux, deux, cinq puis trois décimales.','Compter les décimales des deux facteurs.','assert 147*23==3381 and Rational("14.7")*Rational("2.3")==Rational("33.81") and Rational("1.47")*23==Rational("33.81") and Rational("0.147")*Rational("0.23")==Rational("0.03381") and 147*Rational("0.023")==Rational("3.381")'),
E('Ordre de grandeur',r'Sans poser, choisir le bon résultat. $19{,}8\times5{,}1$ : $10{,}098$ ; $100{,}98$ ; $1\,009{,}8$. Puis $0{,}49\times61$ : $2{,}989$ ; $29{,}89$ ; $298{,}9$.',r'$20\times5=100$ : $\res{100{,}98}$. $0{,}5\times60=30$ : $\res{29{,}89}$.','Arrondir les facteurs pour estimer.','assert Rational("19.8")*Rational("5.1")==Rational("100.98") and Rational("0.49")*61==Rational("29.89")'),
E('Calculer astucieusement',r'Calculer de tête en changeant l’ordre des facteurs : $2{,}5\times7{,}3\times4$ ; $0{,}5\times36{,}8\times2$ ; $1{,}25\times3{,}1\times8$.',r'$2{,}5\times4=10$, donc $\res{73}$. $0{,}5\times2=1$, donc $\res{36{,}8}$. $1{,}25\times8=10$, donc $\res{31}$.','Regrouper les facteurs qui donnent 1 ou 10.','assert Rational("2.5")*Rational("7.3")*4==73 and Rational("0.5")*Rational("36.8")*2==Rational("36.8") and Rational("1.25")*Rational("3.1")*8==31'),
E('Plus petit ou plus grand ?',r'Sans calculer, dire si chaque résultat est plus petit ou plus grand que 24, puis calculer : $24\times0{,}9$ ; $24\times1{,}2$ ; $24\times0{,}05$.',r'$0{,}9<1$ : plus petit, $\res{21{,}6}$. $1{,}2>1$ : plus grand, $\res{28{,}8}$. $0{,}05<1$ : plus petit, $\res{1{,}2}$.','Comparer le second facteur à 1.','assert 24*Rational("0.9")==Rational("21.6") and 24*Rational("1.2")==Rational("28.8") and 24*Rational("0.05")==Rational("1.2")'),
E('Les courses',r'Zoé achète 3 kg de pommes à $2{,}45$ € le kilogramme et $1{,}5$ kg de raisin à $4{,}80$ € le kilogramme. Elle paie avec un billet de 20 €. Combien lui rend-on ?',r'Pommes : $3\times2{,}45=7{,}35$ €. Raisin : $1{,}5\times4{,}80=7{,}20$ €. Total : $14{,}55$ €. Monnaie : $20-14{,}55=\res{5{,}45}$ €.','Calculer chaque achat, puis la monnaie.','assert 3*Rational("2.45")==Rational("7.35") and Rational("1.5")*Rational("4.8")==Rational("7.2") and 20-Rational("14.55")==Rational("5.45")'),
E('Le terrain',r'Un terrain rectangulaire mesure $24{,}5$ m sur $12{,}8$ m. Estimer son aire, puis la calculer exactement.',r'Estimation : $25\times13=325\ \mathrm{m}^2$. Calcul : $245\times128=31\,360$, deux décimales : $\res{313{,}6\ \mathrm{m}^2}$.','Estimer, puis poser le produit des entiers.','assert Rational("24.5")*Rational("12.8")==Rational("313.6") and 245*128==31360'),
E('Le plein',r'Une voiture consomme $5{,}8$ L de carburant pour 100 km. Quelle quantité consomme-t-elle pour 350 km ? Le carburant coûte $1{,}80$ € le litre : quel est le coût du trajet ?',r'350 km, c’est $3{,}5$ fois 100 km : $3{,}5\times5{,}8=\res{20{,}3}$ L. Coût : $20{,}3\times1{,}80=\res{36{,}54}$ €.','Compter les centaines de kilomètres.','assert Rational("3.5")*Rational("5.8")==Rational("20.3") and Rational("20.3")*Rational("1.8")==Rational("36.54")'),
E('Le ruban',r'Un rouleau contient 25 m de ruban. On en coupe 12 morceaux de $1{,}85$ m. Quelle longueur reste-t-il ?',r'$12\times1{,}85=22{,}2$ m. Il reste $25-22{,}2=\res{2{,}8}$ m.','Multiplier, puis soustraire.','assert 12*Rational("1.85")==Rational("22.2") and 25-Rational("22.2")==Rational("2.8")'),
E('L’erreur de virgule',r'Nina écrit : $3{,}6\times0{,}5=18$. Expliquer pourquoi c’est impossible, puis corriger.',r'Multiplier par $0{,}5$, c’est prendre la moitié : le résultat doit être plus petit que $3{,}6$. $36\times5=180$ et il faut deux décimales : $\res{1{,}8}$.','Contrôler avec le sens du calcul.','assert Rational("3.6")*Rational("0.5")==Rational("1.8") and Rational("1.8")<Rational("3.6")')
],reperes=['Additionner et soustraire des décimaux','Multiplier et diviser par 10, 100, 1 000 ou 0,1…','Produit de deux décimaux','Ordre de grandeur et problèmes'],deco='calcul')
